// ManAlert — alert (generated from docs/shell/man-alert.md).
const ManAlert = "ALERT(1)                        Weft Commands                         ALERT(1)\n\n\x1b[38;5;208mNAME\x1b[0m\n  alert — evaluate conditions and dispatch notifications\n\n\x1b[38;5;208mSYNOPSIS\x1b[0m\n    <pipeline> | alert [<condition>] [--notify=<alias>]\n                       [-k <field>] [-t|--tag <field>]\n                       [--duration <dur>] [--average] [--msg <text>]\n\n\x1b[38;5;208mDESCRIPTION\x1b[0m\n  Reads a value from stdin and evaluates it against a condition.\n  If the condition is met, writes an alert message to stderr and,\n  when --notify is supplied, dispatches the alias from /etc/notify.yaml\n  to its Slack and/or PagerDuty targets.\n\n  If no condition is given, the default is \"any\": the alert fires\n  whenever stdin is non-empty.\n\n  Always passes stdin through to stdout unchanged (tee behavior).\n\n  In a cron watch (/cron.d/), incidents are deduplicated on\n  (watch, condition). Subsequent ticks during an open incident\n  update it but don't re-page. When the condition clears, the\n  incident closes.\n\n  From the interactive shell, alert is the supported way to\n  test an alias end-to-end:\n\n    echo \"hello\" | alert --notify=ops\n\n  Without --notify, alert only writes to stderr — that is the\n  dry-run mode.\n\n\x1b[38;5;208mMULTI-ROW MODE\x1b[0m\n  By default alert treats stdin as a single scalar value per tick.\n  With -k, each non-blank line of stdin is evaluated independently,\n  and -k <field> picks the value field. With -t <field> (a.k.a.\n  --tag), another field names the row; each distinct tag opens\n  and closes incidents, and dispatches notifications, independently.\n  Use -t whenever the pipeline can produce more than one row per\n  tick — otherwise multiple rows collapse into the same incident.\n\n  <field> is one of:\n\n  - A 1-indexed whitespace column (-k 2 → second whitespace-split\n    field). Lines are split on whitespace; pre-format with awk/sed/jq\n    so each row is one line of space-separated values.\n  - A .-prefixed JSON path (-k .latency_ms, -k .req.host). Each\n    line is parsed as a single JSON value. Useful when the upstream\n    is jq emitting JSONL.\n\n  A single alert may not mix the two forms across -k and -t.\n\n\x1b[38;5;208mCONDITIONS\x1b[0m\n  - any — fires whenever stdin is non-empty (default)\n  - above <N> — current value is greater than N\n  - below <N> — current value is less than N\n  - eq <N> — current value equals N\n  - neq <N> — current value does not equal N\n  - changed — value differs from previous run\n  - absent — no input received in the window\n  - rising <N>% — value increased by N% compared to previous/window average\n  - falling <N>% — value decreased by N% compared to previous/window average\n\n\x1b[38;5;208mOPTIONS\x1b[0m\n  - --notify=<alias> — dispatch to the named alias in /etc/notify.yaml. Without --notify, alert only writes to stderr.\n  - -k <field> — multi-row mode: each line of stdin is one row, and <field> selects the numeric value. <field> is either a 1-indexed whitespace column (e.g. 2) or a .-prefixed JSON path against the line parsed as JSON (e.g. .req.latency_ms).\n  - -t <field>, --tag <field> — multi-row mode: <field> names this row for per-tag incident dedup and per-tag notifications. Same field grammar as -k. Must agree with -k on positional vs JSON-path. Required when the pipeline can produce more than one row per tick.\n  - --duration <dur> — time window for sustained conditions. For above/below: condition must hold for ALL runs in the window. For rising/falling: compares against the window average. For absent: no non-empty output in the window. Examples: 5m, 1h, 30s.\n  - --average — for above/below with --duration: compare against the rolling average over the window instead of requiring every individual run to match.\n  - --msg <text> — override the default alert message.\n\n\x1b[38;5;208mEXAMPLES\x1b[0m\n    tail -n 500 myapp.log | awk '$LEVEL == \"ERROR\"' | alert --notify=ops\n    check_errors | alert above 50 --notify=critical\n    check_errors | alert above 50 --duration 5m --average --notify=ops\n    check_errors | alert rising 100% --notify=critical\n    cat /log/canary.log | tail -1 | alert absent --duration 10m --notify=ops\n    echo \"integration test\" | alert --notify=ops\n\n    # Multi-row positional: alert per host whose disk use is above 80%.\n    tail /log/shard.log | jq -r 'select(.type==\"disk\") | \"\\(.host) \\(.pct)\"' \\\n        | alert above 80 -k 2 -t 1 --notify=ops\n\n    # Multi-row JSON path: same idea, no `jq -r` re-formatting required.\n    tail /log/shard.log | jq 'select(.type==\"disk\")' \\\n        | alert above 80 -k .pct -t .host --notify=ops\n\n\x1b[38;5;208mSEE ALSO\x1b[0m\n  help, help alerts, vi, cat\n"

// ManChart — chart (generated from docs/shell/man-chart.md).
const ManChart = "CHART(1)                        Weft Commands                         CHART(1)\n\n\x1b[38;5;208mNAME\x1b[0m\n  chart — render a chart in the terminal, from a watch or a pipeline\n\n\x1b[38;5;208mSYNOPSIS\x1b[0m\n    chart <watch> [-t TYPE] [-n LIMIT] [-i INTERVAL] [-f|--follow]\n    <pipeline> | chart [-x <field>] [-y <field>] [-a <fn>]\n                       [--bucket <dur>] [-t TYPE] [--title <text>]\n\n\x1b[38;5;208mDESCRIPTION\x1b[0m\n  chart runs in two forms:\n\n  Watch form — chart <watch> reads recent results from a\n  /cron.d/<watch> and paints a chart in the terminal. The watch\n  name can be given bare (chart errors) or as a path\n  (chart /cron.d/errors). One-shot renders a single frame and\n  returns; --follow enters a live-redraw mode that refreshes every\n  <INTERVAL> until you press q (or Esc, Ctrl+C,\n  Ctrl+D).\n\n  Pipe form — <pipeline> | chart [...] renders the upstream\n  output once and returns to the prompt. The chart stage is the\n  terminal of the pipeline (no further commands after it). Useful for\n  sketching a chart without first committing the pipeline to a saved\n  watch. --follow is not supported in pipe form.\n\n  Charts always self-fit the terminal — they're never paged through\n  less. A resize re-fits in watch --follow mode on the next tick.\n  There is no zoom or scroll: the chart shows the configured window\n  of data, period.\n\n  In watch form, the data point for each result is the last\n  whitespace-separated field of the watch's stdout — matching the\n  multi-row alert convention (alert -k <N>). In pipe form, -x and\n  -y pick fields explicitly; without them, x is the row sequence\n  and y is the last whitespace field of each line.\n\n\x1b[38;5;208mOPTIONS (watch form)\x1b[0m\n  - -t, --type <line|sparkline|bar> — chart kind. Default line.\n    sparkline is a single-line ramp; bar plots one bar per result\n    with the timestamp under it.\n  - -n, --limit <N> — number of recent results to fetch. Default 50.\n  - -i, --interval <DURATION> — redraw interval in --follow\n    mode. Default 1s. Minimum 100ms.\n  - -f, --follow — drop into live-redraw mode. The chart re-fetches\n    and repaints every <INTERVAL> until you press q.\n\n\x1b[38;5;208mOPTIONS (pipe form)\x1b[0m\n  - -x <field> — x source. <field> is either a 1-indexed\n    whitespace column (-x 1) or a .-prefixed JSON path (-x .ts).\n    Default: row sequence (0, 1, 2, …).\n  - -y <field> — y source. Same grammar as -x. Default: last\n    whitespace field of each line. -x and -y may not mix\n    positional with JSON-path in the same call.\n  - -a, --aggregate <fn> — y reduction within an x-group.\n    One of count, sum, avg, min, max, p50, p95,\n    identity. Default identity, or count when --bucket is set.\n  - --bucket <DURATION> — group rows into time buckets on x.\n    Requires x to parse as a timestamp (RFC3339 or epoch seconds).\n    Switches the default chart kind to line.\n  - -t, --type <line|sparkline|bar> — chart kind. Default bar,\n    or line when --bucket is set.\n  - --title <text> — chart title.\n\n\x1b[38;5;208mEXAMPLES\x1b[0m\n    # Watch form\n    chart error-rate                        one-shot line chart\n    chart error-rate -t sparkline           one-line glyph\n    chart error-rate -t bar                 vertical bars by timestamp\n    chart error-rate --follow               live; press q to exit\n\n    # Pipe form: a quick distribution by host\n    cat /log/api.log | jq '{path, latency}' \\\n      | chart -x .path -y .latency -a sum\n\n    # Pipe form: time-bucketed p95 over the current range\n    cat /log/api.log \\\n      | chart -x .ts -y .latency_ms --bucket 1m -a p95\n\n    # Pipe form: just plot a stream of numbers from jq\n    cat /log/api.log | jq '.cpu_pct' | chart\n\n\x1b[38;5;208mRELATED\x1b[0m\n  ls -l /cron.d/ adds a colored sparkline beside each watch name\n  using the same rendering primitives.\n\n\x1b[38;5;208mSEE ALSO\x1b[0m\n  help, help cron, vi, cat\n"

// ManLess — less (generated from docs/shell/man-less.md).
const ManLess = "LESS(1)                         Weft Commands                          LESS(1)\n\n\x1b[38;5;208mNAME\x1b[0m\n  less — page through output one screen at a time\n\n\x1b[38;5;208mSYNOPSIS\x1b[0m\n    <pipeline> | less\n\n\x1b[38;5;208mDESCRIPTION\x1b[0m\n  An in-process pager for weft. Unlike the system less(1) it runs\n  inside the shell — no subprocess, no TTY hand-off, and it works\n  the same way in the web shell as it does in the native CLI.\n\n  When a pipeline ends with | less the query runs to completion,\n  the result is loaded into the pager, and the shell enters\n  ModeLess until you press q.\n\n  Help and man pages auto-page when their output would overflow\n  the viewport — press q to return to the prompt.\n\n\x1b[38;5;208mNAVIGATION\x1b[0m\n    space, Page Down, f, Ctrl+F   forward one screen\n    b, Page Up, Ctrl+B            back one screen\n    j, Down                       forward one line\n    k, Up                         back one line\n    g, gg                         jump to top\n    G                             jump to bottom\n    q, Ctrl+C                     exit the pager\n\n\x1b[38;5;208mSEARCH\x1b[0m\n    /pattern    search forward (case-sensitive substring)\n    n           next match\n    N           previous match\n\n\x1b[38;5;208mSTATUS LINE\x1b[0m\n  Bottom row shows the source title on the left and a percent\n  position on the right. Incremental search and error messages\n  replace the status briefly.\n\n\x1b[38;5;208mSEE ALSO\x1b[0m\n  help, man alert, man range\n"

// ManRange — range (generated from docs/shell/man-range.md).
const ManRange = "RANGE(1)                        Weft Commands                         RANGE(1)\n\n\x1b[38;5;208mNAME\x1b[0m\n  range — display or set the log query time range\n\n\x1b[38;5;208mSYNOPSIS\x1b[0m\n    range\n    range <start>..<end>\n    range <start>..\n\n\x1b[38;5;208mDESCRIPTION\x1b[0m\n  With no arguments, range displays the current query time window.\n\n  With a <start>..<end> argument, range sets the time window used\n  by all subsequent queries. If <end> is omitted, it defaults to\n  now.\n\n  Each side of the range can be:\n\n  \x1b[38;5;208mISO TIMESTAMP (any resolution)\x1b[0m\n    2026-04-12T10:30:00Z    full RFC3339\n    2026-04-12T10:30        minute resolution\n    2026-04-12              day resolution\n    2026-04                 month resolution\n\n  \x1b[38;5;208mRELATIVE DURATION\x1b[0m\n    30m                     30 minutes ago\n    2h                      2 hours ago\n    7d                      7 days ago\n\n  \x1b[38;5;208mNAMED REFERENCES\x1b[0m\n    now                     current time\n    today                   midnight today\n    yesterday               midnight yesterday\n\n\x1b[38;5;208mEXAMPLES\x1b[0m\n    range                   show current range\n    range 2h..              last 2 hours\n    range 30m..             last 30 minutes\n    range 7d..              last 7 days\n    range 1h..10m           from 1 hour ago to 10 minutes ago\n    range yesterday..today  all of yesterday\n    range yesterday..       yesterday to now\n    range 2026-04-01..2026-04-12\n                            specific date range\n    range 2026-04-12T10:00..2026-04-12T11:00\n                            specific hour\n"

